'use strict';

// MODULES //

var factory = require( '@stdlib/ml/base/kmeans/results/factory' );


// MAIN //

/**
* Returns a k-means clustering double-precision floating-point results object.
*
* @name Results
* @constructor
* @type {Function}
* @param {ArrayBuffer} [buffer] - underlying byte buffer
* @param {NonNegativeInteger} [byteOffset] - byte offset
* @param {NonNegativeInteger} [byteLength] - maximum byte length
* @returns {Results} results object
*
* @example
*
* var results = new Results();
* // returns <Results>
*
* results.replicates = 3;
* results.replicate = 1;
* results.metric = 'sqeuclidean';
* results.iterations = 4;
* results.algorithm = 'lloyd';
* results.inertia = 3.28;
* results.k = 4;
* results.samples = 10;
* results.features = 3;
*
* var str = results.toString();
* // returns <string>
*/
var Results = factory( 'float64' );


// EXPORTS //

module.exports = Results;
